package cn.iocoder.yudao.module.aigc.service;

import cn.iocoder.yudao.framework.security.core.util.SecurityFrameworkUtils;
import cn.iocoder.yudao.framework.tenant.core.context.TenantContextHolder;
import cn.iocoder.yudao.module.infra.framework.file.core.utils.FileTypeUtils;
import cn.iocoder.yudao.module.infra.service.file.FileService;
import cn.iocoder.yudao.module.system.api.permission.PermissionApi;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.multipart.MultipartFile;
import java.util.*;
import static cn.iocoder.yudao.module.aigc.service.StudioService.map;

/** Tenant-scoped editorial catalog. Public queries never expose private asset/file IDs. */
@Service
public class ExploreService {
 private final StudioService studio;private final JdbcTemplate db;private final FileService files;private final PermissionApi permissions;
 private static final Set<String> MODES=Set.of("IMAGE","VIDEO","AUDIO","MUSIC");
 public ExploreService(StudioService studio,JdbcTemplate db,FileService files,PermissionApi permissions){this.studio=studio;this.db=db;this.files=files;this.permissions=permissions;}
 private long tenant(){return TenantContextHolder.getRequiredTenantId();}
 public boolean canManage(){Long user=SecurityFrameworkUtils.getLoginUserId();return user!=null&&SecurityFrameworkUtils.getLoginUser().getUserType()==2&&permissions.hasAnyPermissions(user,"aigc:explore:manage");}
 private long operator(){if(SecurityFrameworkUtils.getLoginUserId()==null)throw studio.error(401,"请先登录");if(!canManage())throw studio.error(403,"仅内容运营账号可以管理探索内容");return SecurityFrameworkUtils.getLoginUserId();}
 private Map<String,Object> row(long id,boolean manage){if(manage)operator();return studio.one("SELECT * FROM aigc_explore_content WHERE tenant_id=? AND id=? AND deleted=0"+(manage?"":" AND status='PUBLISHED'"),tenant(),id);}
 @SuppressWarnings("unchecked") private Map<String,Object> object(Object v){if(v instanceof Map<?,?> m)return (Map<String,Object>)m;Object decoded=studio.decode(v,Map.of());if(decoded instanceof Map<?,?> m)return (Map<String,Object>)m;throw studio.error(400,"探索配置必须是对象");}
 private String text(Object value,int max,boolean required){String s=Objects.toString(value,"").trim();if((required&&s.isEmpty())||s.length()>max)throw studio.error(400,"请检查探索内容的文本长度");return s;}
 private Map<String,Object> localized(Object value,int max,boolean required){var m=object(value);var result=new LinkedHashMap<String,Object>();for(String key:List.of("zh-CN","en","es"))result.put(key,text(m.get(key),max,required&&key.equals("zh-CN")));return result;}
 private int integer(Object value,int fallback,int min,int max){try{int n=value==null?fallback:Integer.parseInt(value.toString());if(n>=min&&n<=max)return n;}catch(Exception ignored){}throw studio.error(400,"探索参数超出允许范围");}
 private Map<String,Object> media(long id){return studio.one("SELECT m.*,f.config_id,f.path FROM aigc_explore_media m JOIN infra_file f ON f.id=m.infra_file_id AND f.deleted=0 WHERE m.tenant_id=? AND m.id=? AND m.deleted=0",tenant(),id);}
 private Long mediaId(Object id,String kind){if(id==null||id.toString().isBlank())return null;long value=studio.id(id);var m=media(value);if(!kind.equals(m.get("kind")))throw studio.error(400,"探索媒体类型与内容类型不一致");return value;}
 private String contentPath(Object id,String slot){return "/admin-api/aigc/explore/"+id+"/media/"+slot;}
 private Map<String,Object> dto(Map<String,Object> r,boolean manage){var result=map("id",r.get("id").toString(),"titles",object(r.get("title_i18n")),"descriptions",object(r.get("description_i18n")),"mode",r.get("operation").toString().toLowerCase(Locale.ROOT),"prompt",r.get("prompt"),"parameters",object(r.get("parameters")),"coverPath",r.get("cover_media_id")==null?null:contentPath(r.get("id"),"cover"),"mediaPath",r.get("media_id")==null?null:contentPath(r.get("id"),"original"),"downloadEnabled",Boolean.TRUE.equals(r.get("download_enabled")),"sort",r.get("sort_order"),"status",r.get("status"),"revision",r.get("revision"));
  if(manage)result.putAll(map("coverMediaId",r.get("cover_media_id")==null?null:r.get("cover_media_id").toString(),"mediaId",r.get("media_id")==null?null:r.get("media_id").toString()));return result;}
 public Map<String,Object> catalog(String mode,int offset,int limit){if(!mode.equals("all")&&!MODES.contains(mode.toUpperCase(Locale.ROOT)))throw studio.error(400,"未知探索分类");if(offset<0||offset>100000||limit<1||limit>60)throw studio.error(400,"分页参数错误");String clause=mode.equals("all")?"":" AND operation=?";List<Object> args=new ArrayList<>(List.of(tenant()));if(!mode.equals("all"))args.add(mode.toUpperCase(Locale.ROOT));args.add(limit+1);args.add(offset);var rows=db.queryForList("SELECT * FROM aigc_explore_content WHERE tenant_id=? AND deleted=0 AND status='PUBLISHED'"+clause+" ORDER BY sort_order ASC,id DESC LIMIT ? OFFSET ?",args.toArray());boolean more=rows.size()>limit;return map("items",rows.stream().limit(limit).map(r->dto(r,false)).toList(),"nextOffset",more?offset+limit:null);}
 public Map<String,Object> detail(long id){return dto(row(id,false),false);}
 public Map<String,Object> management(boolean trash){operator();return map("items",db.queryForList("SELECT * FROM aigc_explore_content WHERE tenant_id=? AND deleted=? ORDER BY sort_order ASC,id DESC LIMIT 1000",tenant(),trash).stream().map(r->dto(r,true)).toList());}
 public Map<String,Object> permissions(){return map("canManage",canManage());}
 public List<Map<String,Object>> capabilities(){operator();return db.queryForList("SELECT c.id,m.name,c.operation,c.default_parameters,c.limits_config FROM aigc_model_capability c JOIN ai_model m ON m.id=c.ai_model_id AND m.deleted=0 AND m.status=0 JOIN ai_api_key k ON k.id=m.key_id AND k.deleted=0 AND k.status=0 WHERE c.deleted=0 AND c.status='ENABLED' ORDER BY m.sort,c.id").stream().map(r->map("id",r.get("id").toString(),"name",r.get("name"),"operation",r.get("operation"),"defaults",object(r.get("default_parameters")),"limits",object(r.get("limits_config")))).toList();}
 private Map<String,Object> parameters(Object input,String operation){var p=object(input);var result=new LinkedHashMap<String,Object>();
  for(String key:List.of("ratio","resolution","negativePrompt","voiceDesign"))if(p.containsKey(key))result.put(key,text(p.get(key),key.equals("negativePrompt")?12000:4000,false));
  result.put("count",integer(p.get("count"),1,1,4));if(operation.equals("VIDEO"))result.put("videoSeconds",integer(p.get("videoSeconds"),5,1,120));if(operation.equals("MUSIC"))result.put("musicSeconds",integer(p.get("musicSeconds"),30,5,120));
  if(p.get("capabilityId")!=null&&!p.get("capabilityId").toString().isBlank()){long id=studio.id(p.get("capabilityId"));studio.one("SELECT id FROM aigc_model_capability WHERE id=? AND operation=? AND deleted=0 AND status='ENABLED'",id,operation);result.put("capabilityId",String.valueOf(id));}
  if(p.containsKey("speed")){double speed;try{speed=Double.parseDouble(p.get("speed").toString());}catch(Exception e){throw studio.error(400,"语速参数错误");}if(!Double.isFinite(speed)||speed<0.5||speed>2)throw studio.error(400,"语速参数错误");result.put("speed",speed);}return result;
 }
 @Transactional public String save(Long id,Map<String,Object> body){long user=operator();String operation=text(body.get("mode"),16,true).toUpperCase(Locale.ROOT);if(!MODES.contains(operation))throw studio.error(400,"未知探索分类");String status=text(body.getOrDefault("status","DRAFT"),16,true);if(!Set.of("DRAFT","PUBLISHED").contains(status))throw studio.error(400,"未知发布状态");
  var titles=localized(body.get("titles"),160,true);var descriptions=localized(body.get("descriptions"),1000,false);String prompt=text(body.get("prompt"),12000,true);var parameters=parameters(body.get("parameters"),operation);Long cover=mediaId(body.get("coverMediaId"),"IMAGE"),original=mediaId(body.get("mediaId"),operation.equals("MUSIC")?"AUDIO":operation);
  if(operation.equals("IMAGE")){if(original==null)original=cover;if(cover==null)cover=original;}if(status.equals("PUBLISHED")&&(original==null||cover==null))throw studio.error(400,"发布前请上传封面和对应的原始媒体");
  int sort=integer(body.get("sort"),0,-100000,100000);boolean download=Boolean.TRUE.equals(body.get("downloadEnabled"));
  if(id==null)return String.valueOf(studio.insert("aigc_explore_content",map("tenant_id",tenant(),"title_i18n",studio.encode(titles),"description_i18n",studio.encode(descriptions),"operation",operation,"prompt",prompt,"parameters",studio.encode(parameters),"cover_media_id",cover,"media_id",original,"sort_order",sort,"status",status,"download_enabled",download,"creator",String.valueOf(user),"updater",String.valueOf(user))));
  row(id,true);int revision=integer(body.get("revision"),0,1,Integer.MAX_VALUE);int changed=db.update("UPDATE aigc_explore_content SET title_i18n=?,description_i18n=?,operation=?,prompt=?,parameters=?,cover_media_id=?,media_id=?,sort_order=?,status=?,download_enabled=?,revision=revision+1,updater=? WHERE tenant_id=? AND id=? AND revision=? AND deleted=0",studio.encode(titles),studio.encode(descriptions),operation,prompt,studio.encode(parameters),cover,original,sort,status,download,String.valueOf(user),tenant(),id,revision);if(changed!=1)throw studio.error(409,"探索内容已被修改，请刷新后重试");return id.toString();
 }
 @Transactional public void remove(long id,int revision){long user=operator();row(id,true);if(db.update("UPDATE aigc_explore_content SET deleted=1,status='DRAFT',revision=revision+1,updater=? WHERE tenant_id=? AND id=? AND revision=? AND deleted=0",String.valueOf(user),tenant(),id,revision)!=1)throw studio.error(409,"探索内容已被修改，请刷新后重试");}
 @Transactional public void status(long id,Map<String,Object> body){long user=operator();var current=row(id,true);int revision=integer(body.get("revision"),0,1,Integer.MAX_VALUE);String status=text(body.get("status"),16,true);if(status.equals("DRAFT")){if(db.update("UPDATE aigc_explore_content SET status='DRAFT',revision=revision+1,updater=? WHERE tenant_id=? AND id=? AND revision=? AND deleted=0",String.valueOf(user),tenant(),id,revision)!=1)throw studio.error(409,"探索内容已被修改，请刷新后重试");return;}if(!status.equals("PUBLISHED"))throw studio.error(400,"未知发布状态");var values=dto(current,true);values.put("status",status);values.put("revision",revision);save(id,values);}
 @Transactional public void restore(long id,int revision){long user=operator();if(db.update("UPDATE aigc_explore_content SET deleted=0,status='DRAFT',revision=revision+1,updater=? WHERE tenant_id=? AND id=? AND revision=? AND deleted=1",String.valueOf(user),tenant(),id,revision)!=1)throw studio.error(409,"探索内容已被修改，请刷新后重试");}
 public Map<String,Object> upload(MultipartFile file)throws Exception{operator();if(file.isEmpty()||file.getSize()>50L*1024*1024)throw studio.error(400,"单个文件需大于 0 且不超过 50MB");String name=Objects.toString(file.getOriginalFilename(),"explore-media").replace('\\','/');name=name.substring(name.lastIndexOf('/')+1);return storeMedia(file.getBytes(),name);}
 private Map<String,Object> storeMedia(byte[] bytes,String name){long user=operator();name=text(name,220,true);String mime=FileTypeUtils.getMineType(bytes,name);String kind=mime.startsWith("image/")?"IMAGE":mime.startsWith("video/")?"VIDEO":mime.startsWith("audio/")?"AUDIO":"";if(kind.isBlank()||mime.equals("image/svg+xml")||mime.equals("image/gif"))throw studio.error(400,"探索媒体仅支持静态图片、音频和视频");String url=files.createFile(bytes,name,"aigc/explore/"+tenant()+"/"+UUID.randomUUID(),mime);var f=studio.one("SELECT id FROM infra_file WHERE url=? AND deleted=0 ORDER BY id DESC LIMIT 1",url);long id=studio.insert("aigc_explore_media",map("tenant_id",tenant(),"infra_file_id",f.get("id"),"kind",kind,"mime_type",mime,"file_name",name,"byte_size",bytes.length,"creator",String.valueOf(user)));return map("id",String.valueOf(id),"kind",kind,"name",name);}
 public StudioService.Content content(long id,String slot,boolean admin)throws Exception{if(!Set.of("cover","original").contains(slot))throw studio.error(404,"探索媒体不存在");var r=row(id,admin);Object mediaId=r.get(slot.equals("cover")?"cover_media_id":"media_id");if(mediaId==null)throw studio.error(404,"探索媒体不存在");var m=media(studio.id(mediaId));byte[] bytes=files.getFileContent(studio.id(m.get("config_id")),m.get("path").toString());if(bytes==null)throw studio.error(404,"探索媒体不存在");return new StudioService.Content(bytes,m.get("mime_type").toString(),m.get("file_name").toString());}
}
